const svg=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[n]||iconPaths.apps}</svg>`;
const attr=value=>String(value||'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const faviconUrl=url=>{try{return new URL('/favicon.ico',url).href}catch{return ''}};
const authHeaders=()=>window.havenAccessToken?{Authorization:`Bearer ${window.havenAccessToken}`}:{ };
if(window.crypto?.getRandomValues&&!window.crypto.randomUUID){Object.defineProperty(window.crypto,'randomUUID',{value:()=>{const bytes=window.crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=[...bytes].map(byte=>byte.toString(16).padStart(2,'0'));return `${hex.slice(0,4).join('')}-${hex.slice(4,6).join('')}-${hex.slice(6,8).join('')}-${hex.slice(8,10).join('')}-${hex.slice(10).join('')}`}})}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));

const apps=[];let favoriteAppIds=[];
const appLogoCache=new Map(),appLogoPending=new Map();
const savedSettings=JSON.parse(localStorage.getItem('haven-settings')||'{}');
if(savedSettings.haToken||savedSettings.haUrl){delete savedSettings.haToken;delete savedSettings.haUrl;localStorage.setItem('haven-settings',JSON.stringify(savedSettings))}
(Array.isArray(savedSettings.customApps)?savedSettings.customApps:[]).forEach(app=>{if(app?.name&&app?.url)apps.push({name:String(app.name),type:'Web application',color:'#52645c',mark:String(app.name).slice(0,1).toUpperCase(),url:String(app.url),icon:String(app.icon||''),custom:true,id:String(app.id||app.name)})});
function appCard(app,editable=false){const tile=`<button class="app-tile" data-app="${attr(app.name)}" data-url="${attr(app.url)}"><span class="app-logo" data-logo-url="${attr(app.url)}" style="background:${app.color}"><b>${attr(app.mark)}</b></span><span class="app-meta"><strong>${attr(app.name)}</strong><small>${attr(app.type)}</small></span><i class="online-dot"></i></button>`;return editable?`<div class="app-tile-wrap">${tile}<button type="button" class="favorite-app-button${favoriteAppIds.includes(app.id)?' selected':''}" data-favorite-app="${attr(app.id)}" aria-label="${favoriteAppIds.includes(app.id)?'Remove from':'Add to'} dashboard favorites">★</button></div>`:tile}
const customAppRows=()=>apps.map((app,index)=>`<div class="custom-app-row" data-edit-app="${attr(app.id)}"><span class="custom-app-icon app-logo" data-logo-url="${attr(app.url)}"><b>${attr(app.mark)}</b></span><div class="custom-app-fields"><input data-edit-name value="${attr(app.name)}" aria-label="Application name"><input data-edit-url type="url" value="${attr(app.url)}" aria-label="Application URL"><input data-edit-icon type="url" value="${attr(app.icon)}" placeholder="Optional icon URL" aria-label="Icon URL"></div><div class="custom-app-actions"><button type="button" data-move-app="up" ${index===0?'disabled':''}>↑</button><button type="button" data-move-app="down" ${index===apps.length-1?'disabled':''}>↓</button><button type="button" data-save-app>Save</button><button type="button" class="remove-app" data-remove-app="${attr(app.id)}">Remove</button></div></div>`).join('')||'<div class="integration-empty">No applications added yet.</div>';
const wireLogoFallbacks=()=>document.querySelectorAll('.app-logo img,.custom-app-list img').forEach(img=>img.addEventListener('error',()=>img.remove(),{once:true}));
function renderApps(){const cards=apps.filter(app=>app.url&&app.url!=='#'),chosen=favoriteAppIds.length?favoriteAppIds.map(id=>cards.find(app=>app.id===id)).filter(Boolean):cards.slice(0,5);document.querySelector('#favorite-apps').innerHTML=chosen.map(app=>appCard(app)).join('')||'<div class="integration-empty">Choose favorite applications from the Applications page.</div>';document.querySelector('#all-apps').innerHTML=cards.map(app=>appCard(app,true)).join('')||'<div class="empty-state app-empty"><h2>No applications yet</h2><p>Add your own services from Settings.</p><button class="primary-button" data-page-target="settings">Add application</button></div>';wireLogoFallbacks();queueMicrotask(loadAppLogos)}
function replaceApplications(items){apps.splice(0,apps.length,...items.map(app=>({name:String(app.name),type:'Web application',color:'#52645c',mark:String(app.name).slice(0,1).toUpperCase(),url:String(app.url),icon:String(app.icon||''),custom:true,id:String(app.id||app.name)})));renderApps();const list=document.querySelector('.custom-app-list');if(list){list.innerHTML=customAppRows();wireLogoFallbacks();loadAppLogos()}}
let applicationsSaving=false;
async function saveApplications(items){applicationsSaving=true;try{const response=await fetch('/api/applications',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},cache:'no-store',body:JSON.stringify({applications:items})}),data=await havenJson(response,'Applications');if(!Array.isArray(data.applications))throw new Error('Haven did not confirm the saved application list.');replaceApplications(data.applications);savedSettings.customApps=data.applications;localStorage.setItem('haven-settings',JSON.stringify(savedSettings));return data.applications}finally{applicationsSaving=false}}
async function loadApplications(){if(applicationsSaving)return;try{const response=await fetch('/api/applications',{headers:authHeaders(),cache:'no-store'}),data=await havenJson(response,'Applications');const local=Array.isArray(savedSettings.customApps)?savedSettings.customApps:[];if(!data.applications?.length&&local.length){await saveApplications(local);toast('Existing applications migrated to Haven');return}const incoming=JSON.stringify(data.applications||[]),current=JSON.stringify(savedSettings.customApps||[]);if(incoming!==current)replaceApplications(data.applications||[]);savedSettings.customApps=data.applications||[];localStorage.setItem('haven-settings',JSON.stringify(savedSettings))}catch(error){console.warn('Applications could not be synchronized',error);toast(error.message||'Applications could not be synchronized')}}
async function loadDashboardSettings(){try{let response=await fetch('/api/dashboard',{headers:authHeaders()}),data=await response.json();if(!response.ok)throw new Error(data.error);if(!data.revision&&savedSettings.weatherLocation){response=await fetch('/api/dashboard',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({weatherLocation:savedSettings.weatherLocation})});data=await response.json()}const changed=savedSettings.dashboardRevision!==data.revision||savedSettings.weatherLocation!==data.weatherLocation;Object.assign(savedSettings,{weatherLocation:data.weatherLocation,dashboardRevision:data.revision});localStorage.setItem('haven-settings',JSON.stringify(savedSettings));const form=document.querySelector('#general-settings');if(form)form.elements.weatherLocation.value=data.weatherLocation;if(changed)loadWeather()}catch(error){console.warn('Dashboard settings could not be synchronized',error)}}
renderApps();
