renderQuickActionsEditor();

function closeMobileMenu(){document.querySelector('.sidebar').classList.remove('open');document.querySelector('#sidebar-backdrop').classList.remove('open');document.querySelector('#mobile-menu').setAttribute('aria-expanded','false')}
function toggleMobileMenu(){const open=document.querySelector('.sidebar').classList.toggle('open');document.querySelector('#sidebar-backdrop').classList.toggle('open',open);document.querySelector('#mobile-menu').setAttribute('aria-expanded',String(open))}
function showPage(name){if(!document.querySelector(`#page-${name}`))name='home';document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));document.querySelectorAll('[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===name));closeMobileMenu();history.replaceState(null,'',`${location.pathname}${location.search}#${name}`);window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
document.querySelectorAll('[data-open-settings]').forEach(b=>b.addEventListener('click',()=>showPage('settings')));
document.querySelector('#mobile-menu').addEventListener('click',toggleMobileMenu);
document.querySelector('#mobile-more').addEventListener('click',toggleMobileMenu);
document.querySelector('#sidebar-backdrop').addEventListener('click',closeMobileMenu);
const toast=msg=>{const t=document.querySelector('#toast');t.querySelector('p').textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2800)};
document.addEventListener('click',e=>{const pageTarget=e.target.closest('[data-page-target]');if(pageTarget)showPage(pageTarget.dataset.pageTarget);const external=e.target.closest('[data-external-url]');if(external?.dataset.externalUrl)window.open(external.dataset.externalUrl,'_blank','noopener');const app=e.target.closest('[data-app]');if(app){if(app.dataset.url==='#')toast(`Add the ${app.dataset.app} URL in Settings`);else window.open(app.dataset.url,'_blank','noopener')}const action=e.target.closest('[data-ha-action]');if(action)executeHaAction(action.dataset.entityId,action.dataset.service,action);const calendarEvent=e.target.closest('[data-calendar-day]');if(calendarEvent)focusCalendarAgenda(calendarEvent.dataset.calendarDay)});
const saveSettings=patch=>{Object.assign(savedSettings,patch);localStorage.setItem('haven-settings',JSON.stringify(savedSettings))};
const widgetLabels={weather:'Weather','home-status':'Home status','daily-tasks':'Daily plan','shelf-life':'Tonight’s dinner',whisker:'Whisker',applications:'Applications',plex:'Recently added', 'quick-actions':'Quick actions',vikunja:'Vikunja tasks',immich:'Immich photos',chores:'Chores'};
let currentUser=null,widgetPrefs={order:Object.keys(widgetLabels),hidden:[],sizes:{}};
function applyWidgetPrefs(prefs){widgetPrefs=prefs||widgetPrefs;const canvas=document.querySelector('#dashboard-widgets');for(const id of widgetPrefs.order||[]) {const widget=canvas.querySelector(`[data-widget="${id}"]`);if(widget)canvas.append(widget)}for(const widget of canvas.querySelectorAll('[data-widget]')){const id=widget.dataset.widget,size=widgetPrefs.sizes?.[id]||'medium';widget.classList.toggle('user-hidden',widgetPrefs.hidden?.includes(id));widget.classList.remove('widget-small','widget-medium','widget-wide');widget.classList.add(`widget-${size}`)}}
function renderWidgetEditor(){document.querySelector('#widget-editor-list').innerHTML=(widgetPrefs.order||Object.keys(widgetLabels)).map((id,index)=>`<div class="widget-editor-row" data-widget-control="${id}"><strong>${widgetLabels[id]}</strong><button type="button" data-widget-visible="${id}">${widgetPrefs.hidden?.includes(id)?'Show':'Hide'}</button><select data-widget-size="${id}"><option value="small" ${widgetPrefs.sizes?.[id]==='small'?'selected':''}>Small</option><option value="medium" ${!widgetPrefs.sizes?.[id]||widgetPrefs.sizes[id]==='medium'?'selected':''}>Medium</option><option value="wide" ${widgetPrefs.sizes?.[id]==='wide'?'selected':''}>Wide</option></select><span><button type="button" data-widget-move="${id}" data-direction="-1" ${index===0?'disabled':''}>↑</button><button type="button" data-widget-move="${id}" data-direction="1" ${index===(widgetPrefs.order.length-1)?'disabled':''}>↓</button></span></div>`).join('')}
function setCustomizeMode(open){document.querySelector('#widget-editor').classList.toggle('hidden',!open);document.querySelectorAll('.dashboard-widget').forEach(widget=>{widget.classList.toggle('customizing',open);widget.draggable=open});if(open)renderWidgetEditor()}
document.querySelector('#customize-dashboard').addEventListener('click',()=>setCustomizeMode(true));
document.querySelector('#widget-editor-close').addEventListener('click',()=>setCustomizeMode(false));
document.querySelector('#widget-editor-list').addEventListener('click',event=>{const visible=event.target.closest('[data-widget-visible]'),move=event.target.closest('[data-widget-move]');if(!visible&&!move)return;if(visible){const id=visible.dataset.widgetVisible,hidden=new Set(widgetPrefs.hidden||[]);hidden.has(id)?hidden.delete(id):hidden.add(id);widgetPrefs.hidden=[...hidden]}if(move){const id=move.dataset.widgetMove,index=widgetPrefs.order.indexOf(id),next=index+Number(move.dataset.direction);if(next>=0&&next<widgetPrefs.order.length)[widgetPrefs.order[index],widgetPrefs.order[next]]=[widgetPrefs.order[next],widgetPrefs.order[index]]}applyWidgetPrefs(widgetPrefs);renderWidgetEditor()});
document.querySelector('#widget-editor-list').addEventListener('change',event=>{if(!event.target.matches('[data-widget-size]'))return;widgetPrefs.sizes={...(widgetPrefs.sizes||{}),[event.target.dataset.widgetSize]:event.target.value};applyWidgetPrefs(widgetPrefs)});
document.querySelector('#save-widget-layout').addEventListener('click',async()=>{try{const response=await fetch('/api/me',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({widgets:widgetPrefs})});if(!response.ok)throw new Error();setCustomizeMode(false);toast('Dashboard layout saved for your Keycloak user')}catch{toast('Dashboard layout could not be saved')}});
let draggedWidget=null;document.querySelector('#dashboard-widgets').addEventListener('dragstart',event=>{draggedWidget=event.target.closest('[data-widget]');if(draggedWidget)draggedWidget.classList.add('dragging')});document.querySelector('#dashboard-widgets').addEventListener('dragover',event=>{if(!draggedWidget)return;event.preventDefault();const target=event.target.closest('[data-widget]');if(target&&target!==draggedWidget)target.before(draggedWidget)});document.querySelector('#dashboard-widgets').addEventListener('dragend',()=>{if(!draggedWidget)return;draggedWidget.classList.remove('dragging');widgetPrefs.order=[...document.querySelectorAll('#dashboard-widgets [data-widget]')].map(widget=>widget.dataset.widget);draggedWidget=null;renderWidgetEditor()});
async function loadMe(){try{const response=await fetch('/api/me',{headers:authHeaders()}),me=await response.json();if(!response.ok)throw new Error(me.error);currentUser=me;favoriteAppIds=me.favoriteAppIds||[];document.querySelector('#welcome-name').textContent=me.name;document.querySelector('#sidebar-name').textContent=me.name;document.querySelector('#sidebar-username').textContent=me.username?`@${me.username}`:'Keycloak account';document.querySelectorAll('.avatar').forEach(a=>a.textContent=me.name.slice(0,2).toUpperCase());applyWidgetPrefs(me.widgets);renderApps();await loadVikunjaUsers()}catch(error){console.warn('Keycloak profile could not be loaded',error)}}
document.querySelector('#all-apps').addEventListener('click',async event=>{const button=event.target.closest('[data-favorite-app]');if(!button)return;event.preventDefault();event.stopPropagation();const id=button.dataset.favoriteApp;favoriteAppIds=favoriteAppIds.includes(id)?favoriteAppIds.filter(item=>item!==id):[...favoriteAppIds,id];try{const response=await fetch('/api/me',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({favoriteAppIds})});if(!response.ok)throw new Error();renderApps();toast('Dashboard favorites updated')}catch{toast('Favorite could not be saved')}});
async function saveVikunjaMapping(userId,rejected=false){const response=await fetch('/api/me',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({vikunjaUserId:userId,vikunjaRejected:rejected})});if(!response.ok)throw new Error();await Promise.all([loadVikunjaUsers(),loadVikunja()])}
async function havenJson(response,label){const text=await response.text(),type=response.headers.get('content-type')||'';if(/^\s*</.test(text)||!type.includes('json'))throw new Error(`${label} received a web page instead of API data. Refresh Haven after redeploying, then try again.`);let data;try{data=JSON.parse(text)}catch{throw new Error(`${label} returned invalid data.`)}if(!response.ok)throw new Error(data.error||`${label} failed (${response.status})`);return data}
async function loadVikunjaUsers(){const target=document.querySelector('#vikunja-user-mapping'),dashboardTarget=document.querySelector('#vikunja-mapping');try{const response=await fetch('/api/vikunja/users',{headers:authHeaders(),cache:'no-store'}),data=await havenJson(response,'Vikunja');const selected=data.users.find(user=>user.id===data.selectedUserId),suggested=data.suggested;if(selected){target.innerHTML=`Mapped to <strong>${attr(selected.name)}</strong>. <button type="button" data-vikunja-clear>Use a different user</button>`;dashboardTarget.innerHTML=''}else if(suggested&&suggested.id!==data.tokenOwner?.id){const markup=`<div class="vikunja-map"><span>Is <strong>${attr(suggested.name)}</strong> you in Vikunja?</span><div><button type="button" data-vikunja-accept="${suggested.id}">✓ Yes</button><button type="button" data-vikunja-reject>× No</button></div></div>`;target.innerHTML=markup;dashboardTarget.innerHTML=markup}else{target.innerHTML=`<div class="vikunja-map"><span>Using API-token owner <strong>${attr(data.tokenOwner?.name||'Vikunja user')}</strong>. Mapping is only needed for another household member.</span></div><div class="vikunja-user-picker"><select data-vikunja-select><option value="">Choose a different user</option>${data.users.filter(user=>user.id!==data.tokenOwner?.id).map(user=>`<option value="${user.id}">${attr(user.name)}</option>`).join('')}</select><button type="button" data-vikunja-save-user>Use selected user</button></div>`;dashboardTarget.innerHTML=''}}catch(error){target.textContent=error.message||'Save Vikunja first to discover users.'}}
document.addEventListener('click',async event=>{try{const accept=event.target.closest('[data-vikunja-accept]');if(accept)await saveVikunjaMapping(Number(accept.dataset.vikunjaAccept));if(event.target.closest('[data-vikunja-reject]'))await saveVikunjaMapping(null,true);if(event.target.closest('[data-vikunja-clear]'))await saveVikunjaMapping(null,false)}catch{toast('Vikunja mapping could not be saved')}});
document.addEventListener('click',async event=>{if(!event.target.closest('[data-vikunja-save-user]'))return;const select=document.querySelector('[data-vikunja-select]');if(!select?.value){toast('Choose a Vikunja user first');return}try{await saveVikunjaMapping(Number(select.value));toast('Vikunja user mapping saved')}catch{toast('Vikunja mapping could not be saved')}});
document.querySelector('#general-settings').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.currentTarget),weatherLocation=data.get('weatherLocation').trim();try{const response=await fetch('/api/dashboard',{method:'PUT',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({weatherLocation})}),result=await response.json();if(!response.ok)throw new Error(result.error);Object.assign(savedSettings,{...result,dashboardRevision:result.revision});localStorage.setItem('haven-settings',JSON.stringify(savedSettings));toast('Dashboard weather synced to every device');loadWeather()}catch(error){toast(error.message||'Dashboard settings could not be saved')}});
document.querySelector('#apps-settings').addEventListener('submit',e=>{e.preventDefault();const urls={};e.currentTarget.querySelectorAll('[data-app-url]').forEach(input=>urls[input.dataset.appUrl]=input.value.trim());saveSettings({apps:urls});toast('Application links saved')});
document.querySelector('#add-app').addEventListener('click',async()=>{const form=document.querySelector('#apps-settings'),name=form.elements.newAppName.value.trim(),rawUrl=form.elements.newAppUrl.value.trim();if(!name||!rawUrl){toast('Enter an application name and URL');return}let url;try{url=new URL(rawUrl);if(!['http:','https:'].includes(url.protocol))throw new Error()}catch{toast('Enter a valid http or https URL');return}try{await saveApplications([...apps.map(({id,name,url,icon})=>({id,name,url,icon})),{id:window.crypto?.randomUUID?.()||`${Date.now()}`,name,url:url.href.replace(/\/$/,''),icon:''}]);form.elements.newAppName.value='';form.elements.newAppUrl.value='';toast(`${name} added`)}catch(error){toast(error.message||'Application could not be added')}});
document.querySelector('#apps-settings').addEventListener('click',async event=>{const button=event.target.closest('[data-remove-app]');if(!button)return;try{await saveApplications(apps.filter(app=>app.id!==button.dataset.removeApp).map(({id,name,url,icon})=>({id,name,url,icon})));toast('Application removed')}catch(error){toast(error.message||'Application could not be removed')}});
document.querySelector('#apps-settings').addEventListener('click',async event=>{const row=event.target.closest('[data-edit-app]');if(!row)return;const id=row.dataset.editApp,index=apps.findIndex(app=>app.id===id);if(index<0)return;try{if(event.target.closest('[data-save-app]')){const name=row.querySelector('[data-edit-name]').value.trim(),url=row.querySelector('[data-edit-url]').value.trim(),icon=row.querySelector('[data-edit-icon]').value.trim();if(!name||!url)throw new Error('Name and URL are required');const next=apps.map(app=>({id:app.id,name:app.name,url:app.url,icon:app.icon||''}));next[index]={id,name,url,icon};await saveApplications(next);toast('Application updated')}const move=event.target.closest('[data-move-app]')?.dataset.moveApp;if(move){const target=move==='up'?index-1:index+1;if(target<0||target>=apps.length)return;const next=apps.map(app=>({id:app.id,name:app.name,url:app.url,icon:app.icon||''}));[next[index],next[target]]=[next[target],next[index]];await saveApplications(next);toast('Application order updated')}}catch(error){toast(error.message||'Application could not be updated')}});
document.querySelector('#export-backup').addEventListener('click',async()=>{try{const response=await fetch('/api/backup',{headers:authHeaders(),cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Backup failed');const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`haven-backup-${new Date().toISOString().slice(0,10)}.haven`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Encrypted backup downloaded')}catch(error){toast(error.message||'Backup failed')}});
document.querySelector('#restore-backup').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(!confirm('Restore this Haven backup? Current settings will be replaced.')){event.target.value='';return}try{const response=await fetch('/api/backup',{method:'POST',headers:{...authHeaders(),'Content-Type':'application/octet-stream'},body:file}),data=await response.json();if(!response.ok)throw new Error(data.error||'Restore failed');toast('Backup restored. Reloading Haven…');setTimeout(()=>location.reload(),1000)}catch(error){toast(error.message||'Restore failed')}finally{event.target.value=''}});
document.querySelector('#add-quick-action').addEventListener('click',()=>{const form=document.querySelector('#integration-settings'),name=form.elements.quickActionName.value.trim(),entityId=form.elements.quickActionEntity.value.trim(),service=form.elements.quickActionService.value;if(!name||!/^[a-z_]+\.[a-zA-Z0-9_]+$/.test(entityId)){toast('Enter a name and valid Home Assistant entity ID');return}quickActionsDraft.push({id:window.crypto?.randomUUID?.()||String(Date.now()),name,entityId,service});form.elements.quickActionName.value='';form.elements.quickActionEntity.value='';renderQuickActionsEditor()});
document.querySelector('#quick-actions-editor').addEventListener('click',e=>{const button=e.target.closest('[data-remove-quick-action]');if(!button)return;quickActionsDraft=quickActionsDraft.filter(action=>action.id!==button.dataset.removeQuickAction);renderQuickActionsEditor()});
document.querySelector('#integration-settings').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form),setup=data.get('setupToken'),payload={homeAssistant:{url:data.get('homeAssistantUrl').trim(),token:data.get('homeAssistantToken'),calendarEntity:data.get('homeAssistantCalendar').trim(),whiskerEntity:data.get('homeAssistantWhisker').trim(),quickActions:quickActionsDraft},plex:{url:data.get('plexUrl').trim(),token:data.get('plexToken')},shelfLife:{url:data.get('shelfLifeUrl').trim(),apiKey:data.get('shelfLifeApiKey')},sentinel:{url:data.get('sentinelUrl').trim()},vikunja:{url:data.get('vikunjaUrl').trim(),token:data.get('vikunjaToken')},immich:{url:data.get('immichUrl').trim(),apiKey:data.get('immichApiKey')},chores:{url:data.get('choresUrl').trim()},calendar:{icsUrl:data.get('calendarUrl').trim()},arrs:{}};for(const id of Object.keys(arrLabels))payload.arrs[id]={url:data.get(`${id}Url`).trim(),apiKey:data.get(`${id}ApiKey`)};try{const headers={'Content-Type':'application/json',...authHeaders()};if(setup)headers['X-Haven-Setup-Token']=setup;const response=await fetch('/api/setup/integrations',{method:'POST',headers,body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){toast(result.error||'Integration settings were rejected');return}toast('Integrations saved and dashboard refreshed');form.elements.setupToken.value='';form.elements.homeAssistantToken.value='';form.elements.plexToken.value='';form.elements.shelfLifeApiKey.value='';form.elements.vikunjaToken.value='';form.elements.immichApiKey.value='';for(const id of Object.keys(arrLabels))form.elements[`${id}ApiKey`].value='';const savedStatus=await loadIntegrationStatus();await loadConnectedData();const checks=await verifyIntegrations(savedStatus),saveResult=document.querySelector('#integration-save-result');saveResult.textContent=checks||'Settings saved. Add a service above to populate its dashboard section.';saveResult.classList.add('success')}catch{toast('Could not save integrations')}});
async function verifyIntegrations(status){const services=[];if(status?.homeAssistant?.configured)services.push(['homeAssistant','Home Assistant']);if(status?.homeAssistant?.calendarEntity)services.push(['homeAssistantCalendar','HA calendar']);if(status?.plex?.configured)services.push(['plex','Plex']);if(status?.vikunja?.configured)services.push(['vikunja','Vikunja']);if(status?.immich?.configured)services.push(['immich','Immich']);if(status?.chores?.configured)services.push(['chores','Chore app']);if(status?.calendar?.configured)services.push(['calendar','ICS calendar']);for(const id of Object.keys(arrLabels))if(status?.arrs?.[id]?.configured)services.push([id,arrLabels[id]]);if(!services.length)return '';const results=await Promise.all(services.map(async([id,label])=>{try{const response=await fetch(`/api/integrations/test?service=${encodeURIComponent(id)}`,{headers:authHeaders()});return `${label}: ${response.ok?'connected':'could not connect'}`}catch{return `${label}: could not connect`}}));return `Saved and checked — ${results.join(' · ')}`}
document.querySelectorAll('[data-test-integration]').forEach(button=>button.addEventListener('click',async()=>{if(!window.havenAccessToken){toast('Sign in before testing integrations');return}button.disabled=true;const service=button.dataset.testIntegration;try{const vikunja=service==='vikunja',endpoint=`/api/integrations/test?service=${encodeURIComponent(service)}&_=${Date.now()}`,response=await fetch(endpoint,{headers:{Authorization:`Bearer ${window.havenAccessToken}`},cache:'no-store'}),result=await havenJson(response,vikunja?'Vikunja':'Connection');if(result.ok===false)throw new Error(result.error||'Connection failed');if(vikunja){const state=document.querySelector('#vikunja-state');state.textContent='Connected';state.classList.add('connected')}toast('Connection successful')}catch(error){if(service==='vikunja'){const state=document.querySelector('#vikunja-state');state.textContent='Saved · connection failed';state.classList.remove('connected');document.querySelector('#vikunja-user-mapping').textContent=error.message||'Vikunja connection failed'}toast(error.message||'Connection test failed')}finally{button.disabled=false}}));
document.querySelector('#keycloak-settings').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form),payload={enabled:data.get('enabled')==='on',url:data.get('url').trim(),realm:data.get('realm').trim(),clientId:data.get('clientId').trim()};const setupToken=data.get('setupToken');if(!setupToken){toast('Enter the Haven setup token from Portainer');return}try{const response=await fetch('/api/setup/keycloak',{method:'POST',headers:{'Content-Type':'application/json','X-Haven-Setup-Token':setupToken},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){toast(result.error||'Authentication settings were rejected');return}toast('Keycloak settings saved — starting sign-in');setTimeout(()=>location.replace(`${location.origin}${location.pathname}`),900)}catch{toast('Could not save authentication settings')}});
async function loadIntegrationStatus(){try{const status=await (await fetch('/api/integrations',{headers:authHeaders()})).json();if(status.version)document.querySelector('#version-badge').textContent=`v${status.version}`;const auth=status.keycloak||{},keycloakForm=document.querySelector('#keycloak-settings');keycloakForm.elements.url.value=auth.url||'';keycloakForm.elements.realm.value=auth.realm||'';keycloakForm.elements.clientId.value=auth.clientId||'haven';keycloakForm.elements.enabled.checked=Boolean(auth.enabled);document.querySelector('#auth-status').textContent=auth.configured?`Connected to ${auth.realm}`:'Not configured · use Settings below';const form=document.querySelector('#integration-settings'),haConfigured=Boolean(status.homeAssistant?.configured),haState=document.querySelector('#ha-status-label');if(status.homeAssistant?.url)form.elements.homeAssistantUrl.value=status.homeAssistant.url;if(status.homeAssistant?.calendarEntity!==undefined)form.elements.homeAssistantCalendar.value=status.homeAssistant.calendarEntity;if(Array.isArray(status.homeAssistant?.quickActions)){quickActionsDraft=status.homeAssistant.quickActions;renderQuickActionsEditor()}haState.textContent=haConfigured?'Configured':'Not configured';haState.classList.toggle('connected',haConfigured);document.querySelector('#ha-status-dot').classList.toggle('connected',haConfigured);if(status.plex?.url){form.elements.plexUrl.value=status.plex.url;const library=document.querySelector('#plex-library-button');library.dataset.externalUrl=status.plex.url;library.disabled=false}else document.querySelector('#plex-library-button').disabled=true;document.querySelector('#plex-state').textContent=status.plex?.configured?'Configured':'Not configured';document.querySelector('#plex-state').classList.toggle('connected',Boolean(status.plex?.configured));if(status.vikunja?.url)form.elements.vikunjaUrl.value=status.vikunja.url;const vikunjaState=document.querySelector('#vikunja-state');vikunjaState.textContent=status.vikunja?.configured?'Configured':'Not configured';vikunjaState.classList.toggle('connected',Boolean(status.vikunja?.configured));if(status.immich?.url)form.elements.immichUrl.value=status.immich.url;const immichState=document.querySelector('#immich-state');immichState.textContent=status.immich?.configured?'Configured for you':'Not configured';immichState.classList.toggle('connected',Boolean(status.immich?.configured));if(status.chores?.url)form.elements.choresUrl.value=status.chores.url;const choresState=document.querySelector('#chores-state');choresState.textContent=status.chores?.configured?'Configured':'Not configured';choresState.classList.toggle('connected',Boolean(status.chores?.configured));document.querySelector('#calendar-state').textContent=status.calendar?.configured?'Configured · URL saved':'Not configured';document.querySelector('#calendar-state').classList.toggle('connected',Boolean(status.calendar?.configured));for(const id of Object.keys(arrLabels)){if(status.arrs?.[id]?.url)form.elements[`${id}Url`].value=status.arrs[id].url;const state=document.querySelector(`#${id}-state`),configured=Boolean(status.arrs?.[id]?.configured);state.textContent=configured?'Configured':'Not configured';state.classList.toggle('connected',configured)}for(const panel of document.querySelectorAll('[data-shared-integration]')){panel.classList.toggle('shared-readonly',!status.canManageShared);for(const control of panel.querySelectorAll('input,select,button')){if(control.matches('input,textarea'))control.readOnly=!status.canManageShared;else control.disabled=!status.canManageShared}}const appsForm=document.querySelector('#apps-settings');appsForm.classList.toggle('shared-readonly',!status.canManageShared);for(const control of appsForm.querySelectorAll('input,button')){if(control.matches('input'))control.readOnly=!status.canManageShared;else control.disabled=!status.canManageShared};return status}catch{document.querySelector('#ha-status-label').textContent='Server status unavailable';return null}}
loadIntegrationStatus();
async function loadHouseholdExtrasStatus(){try{const status=await (await fetch('/api/integrations',{headers:authHeaders(),cache:'no-store'})).json(),form=document.querySelector('#integration-settings');if(status.homeAssistant?.whiskerEntity!==undefined)form.elements.homeAssistantWhisker.value=status.homeAssistant.whiskerEntity;if(status.shelfLife?.url)form.elements.shelfLifeUrl.value=status.shelfLife.url;if(status.sentinel?.url)form.elements.sentinelUrl.value=status.sentinel.url;const shelfState=document.querySelector('#shelf-life-state'),shelfConfigured=Boolean(status.shelfLife?.configured);shelfState.textContent=shelfConfigured?'Configured':'Needs URL and API key';shelfState.classList.toggle('connected',shelfConfigured);const sentinelState=document.querySelector('#sentinel-state'),sentinelConfigured=Boolean(status.sentinel?.configured);sentinelState.textContent=sentinelConfigured?'Configured':'Not configured';sentinelState.classList.toggle('connected',sentinelConfigured)}catch{}}
loadHouseholdExtrasStatus();
const search=document.querySelector('#search');search.addEventListener('input',()=>{const q=search.value.toLowerCase();document.querySelectorAll('.app-tile').forEach(el=>el.style.display=el.dataset.app.toLowerCase().includes(q)?'flex':'none')});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();search.focus()}if(e.key==='Escape')search.blur()});
const now=new Date();document.querySelector('#today-label').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});const hour=now.getHours();document.querySelector('.welcome-row h1').firstChild.textContent=`Good ${hour<12?'morning':hour<17?'afternoon':'evening'}, `;
if(savedSettings.weatherLocation)document.querySelector('.weather-place').innerHTML=`${svg('pin')} ${savedSettings.weatherLocation}`;

let installPrompt=null;const installButtons=[document.querySelector('#install-app'),document.querySelector('#settings-install')];window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;document.querySelector('#install-app').classList.remove('hidden')});installButtons.forEach(button=>button?.addEventListener('click',async()=>{if(!installPrompt){toast('Use your browser menu to add Haven to the home screen');return}await installPrompt.prompt();installPrompt=null;document.querySelector('#install-app').classList.add('hidden')}));window.addEventListener('appinstalled',()=>toast('Haven installed successfully'));
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(error=>console.warn('Service worker registration failed',error)));

const weatherIcon=code=>code===0?'mini-sun':code<=3?'mini-cloud':code>=71&&code<=77?'mini-snow':'mini-rain';
async function loadWeather(){const location=savedSettings.weatherLocation||'San Francisco, CA',place=document.querySelector('.weather-place'),temperature=document.querySelector('.temperature'),condition=document.querySelector('.condition'),forecast=document.querySelector('#weather-forecast');place.innerHTML=`${svg('pin')} ${attr(location)}`;condition.textContent='Loading current conditions…';try{const response=await fetch(`/api/weather?location=${encodeURIComponent(location)}`),data=await response.json();if(!response.ok)throw new Error(data.error);place.innerHTML=`${svg('pin')} ${attr(data.location)}`;temperature.textContent=`${data.temperature}°`;condition.textContent=data.condition;forecast.innerHTML=data.hourly.map((hour,index)=>{const time=index===0?'NOW':new Date(hour.time).toLocaleTimeString([],{hour:'numeric'});return `<div><span>${attr(time)}</span><i class="${weatherIcon(hour.code)}"></i><strong>${hour.temperature}°</strong></div>`}).join('')}catch(error){temperature.textContent='—';condition.textContent=error.message||'Weather unavailable';forecast.innerHTML=''}}
function attachAppLogo(logo,source,key){if(!logo.isConnected||logo.querySelector('img'))return;const image=document.createElement('img');image.src=source;image.alt='';image.addEventListener('error',()=>{image.remove();if(appLogoCache.get(key)===source){appLogoCache.delete(key);URL.revokeObjectURL(source)}},{once:true});logo.append(image)}
async function loadAppLogos(){await Promise.all([...document.querySelectorAll('[data-logo-url]')].map(async logo=>{if(logo.querySelector('img'))return;const app=apps.find(item=>item.url===logo.dataset.logoUrl),name=app?.name||logo.closest('[data-app]')?.dataset.app||'',key=`${logo.dataset.logoUrl}\n${app?.icon||''}`;try{if(appLogoCache.has(key)){attachAppLogo(logo,appLogoCache.get(key),key);return}let pending=appLogoPending.get(key);if(!pending){pending=(async()=>{const response=await fetch(`/api/app-icon?url=${encodeURIComponent(logo.dataset.logoUrl)}&icon=${encodeURIComponent(app?.icon||'')}&name=${encodeURIComponent(name)}&v=4`,{headers:authHeaders(),cache:'no-store'});if(!response.ok||response.status===204)return '';const source=URL.createObjectURL(await response.blob());appLogoCache.set(key,source);return source})().finally(()=>appLogoPending.delete(key));appLogoPending.set(key,pending)}const source=await pending;if(source)attachAppLogo(logo,source,key)}catch(error){console.warn('Application icon could not be loaded',logo.dataset.logoUrl,error)}}))}
const controlService=entity=>entity.domain==='lock'?(entity.state==='locked'?'unlock':'lock'):entity.domain==='cover'?(entity.state==='open'?'close_cover':'open_cover'):entity.domain==='scene'||entity.domain==='script'?'turn_on':entity.domain==='automation'?'trigger':'toggle';
