function calendarEventIcon(summary=''){const explicit=String(summary).match(/\p{Extended_Pictographic}/u)?.[0];if(explicit)return explicit;const text=String(summary).toLowerCase(),rules=[[/birthday|anniversary/,'🎂'],[/bill|payment|renewal|mortgage|invoice|due/,'💳'],[/concert|music|band|show/,'🎵'],[/trip|vacation|flight|travel|hotel/,'✈️'],[/doctor|dentist|medical|appointment/,'🩺'],[/school|class|college|homework/,'🎓'],[/meeting|club|volunteer|civic/,'🤝'],[/trash|garbage|recycling/,'🗑️'],[/holiday|party|celebration/,'🎉'],[/movie|film|cinema/,'🎬']];return rules.find(([pattern])=>pattern.test(text))?.[1]||'📅'}
