let calendarCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1);
const calendarDayKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
function calendarEventDays(event){if(event.allDay&&event.date){const days=[],cursor=new Date(`${event.date}T00:00:00`),exclusiveEnd=event.endDate?new Date(`${event.endDate}T00:00:00`):new Date(cursor.getTime()+86400000);while(cursor<exclusiveEnd&&days.length<366){days.push(calendarDayKey(cursor));cursor.setDate(cursor.getDate()+1)}return days}const start=new Date(event.start),end=new Date(event.end||event.start),last=new Date(Math.max(start.getTime(),end.getTime()-1)),days=[];for(const cursor=new Date(start.getFullYear(),start.getMonth(),start.getDate());cursor<=last&&days.length<366;cursor.setDate(cursor.getDate()+1))days.push(calendarDayKey(cursor));return days}
