async function loadDailyPlanner(){const input=document.querySelector('#daily-date'),list=document.querySelector('#daily-task-list');input.value=dailySelectedDate;try{const tasks=await fetchDailyTasks(dailySelectedDate);list.innerHTML=tasks.length?tasks.sort((a,b)=>(a.done-b.done)||(a.time||'99:99').localeCompare(b.time||'99:99')).map(task=>dailyTaskMarkup(task)).join(''):'<div class="empty-state daily-empty"><h2>Nothing planned</h2><p>Add the small things you need to get done this day.</p></div>'}catch(error){list.innerHTML=`<div class="integration-empty">${attr(error.message)}</div>`}}
