document.querySelector('#daily-date').addEventListener('change',event=>{dailySelectedDate=event.target.value||localDateKey(new Date());loadDailyPlanner()});
document.querySelector('#daily-prev').addEventListener('click',()=>{const date=new Date(`${dailySelectedDate}T12:00:00`);date.setDate(date.getDate()-1);dailySelectedDate=localDateKey(date);loadDailyPlanner()});
document.querySelector('#daily-next').addEventListener('click',()=>{const date=new Date(`${dailySelectedDate}T12:00:00`);date.setDate(date.getDate()+1);dailySelectedDate=localDateKey(date);loadDailyPlanner()});
document.querySelector('#daily-today').addEventListener('click',()=>{dailySelectedDate=localDateKey(new Date());loadDailyPlanner()});
async function loadShelfLife(){const widget=document.querySelector('#shelf-life-widget'),content=document.querySelector('#shelf-life-dinner');try{const response=await fetch(`/api/shelf-life/dinner?date=${localDateKey(new Date())}`,{headers:authHeaders(),cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error);widget.classList.remove('integration-unavailable');document.querySelector('#shelf-life-open').dataset.externalUrl=data.url;content.innerHTML=data.dinner?`<strong>${attr(data.dinner.title)}</strong>${data.dinner.notes?`<p>${attr(data.dinner.notes)}</p>`:''}`:'<div class="integration-empty">No dinner is scheduled for tonight.</div>'}catch(error){widget.classList.add('integration-unavailable');content.innerHTML=`<div class="integration-empty">${attr(error.message||'Connect Shelf Life in Integrations.')}</div>`}}
async function loadWhisker(){const check=document.querySelector('#whisker-check'),content=document.querySelector('#whisker-status');try{const response=await fetch('/api/home-assistant/whisker',{headers:authHeaders(),cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error);check.textContent='✓';content.innerHTML=`<strong>${attr(data.state)}${data.unit?` ${attr(data.unit)}`:''}</strong><small>${attr(data.name)}</small>${data.details?.length?`<div class="whisker-details">${data.details.slice(0,3).map(item=>`<span><b>${attr(item.value)}</b>${attr(item.label)}</span>`).join('')}</div>`:''}`}catch(error){check.textContent='—';content.innerHTML=`<div class="integration-empty">${attr(error.message||'Whisker status unavailable.')}</div>`}}
async function loadSentinel(){const pill=document.querySelector('#sentinel-status'),label=pill.querySelector('b');try{const response=await fetch('/api/sentinel/status',{headers:authHeaders(),cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error);pill.dataset.externalUrl=data.url;label.textContent=data.status;pill.classList.toggle('degraded',!data.healthy);pill.title=(data.dependencies||[]).map(item=>`${item.name}: ${item.status}`).join(' · ')||data.status}catch(error){label.textContent='Sentinel unavailable';pill.classList.add('degraded');pill.title=error.message||'Sentinel could not be reached'}}
async function loadConnectedData(){loadWeather();if(window.havenAccessToken)await Promise.all([loadMe(),loadIntegrationStatus(),loadHouseholdExtrasStatus(),loadDashboardSettings(),loadApplications(),loadAppLogos(),loadPlex(),loadVikunja(),loadImmich(),loadChores(),loadHomeAssistant(),loadCalendar(),loadDailyPlanner(),loadDailyWidget(),loadShelfLife(),loadWhisker(),loadSentinel(),loadNotifications()])}
async function synchronizeDevices(){if(!window.havenAccessToken||document.hidden)return;await Promise.all([loadDashboardSettings(),loadApplications()])}
setInterval(synchronizeDevices,10000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)synchronizeDevices()});
window.addEventListener('focus',synchronizeDevices);

function keycloakErrorMessage(error){const query=new URLSearchParams(location.search),description=query.get('error_description'),code=query.get('error');if(description||code)return description||code;if(typeof error==='string')return error;if(error?.message)return error.message;if(error?.error_description)return error.error_description;if(error?.error)return typeof error.error==='string'?error.error:JSON.stringify(error.error);try{return JSON.stringify(error)}catch{return 'Keycloak sign-in failed'}}
function clearFailedAuthCallback(){const url=new URL(location.href),keys=['error','error_description','error_uri','session_state','iss','code','state'];let changed=false;for(const key of keys)if(url.searchParams.has(key)){url.searchParams.delete(key);changed=true}if(changed)history.replaceState({},'',`${url.pathname}${url.search}${url.hash}`)}
async function start(){let config={auth:{enabled:false},user:{name:'Mike'}};try{config={...config,...(await import('./config.js')).default}}catch{}const app=document.querySelector('#app'),login=document.querySelector('#login-screen');let keycloak=null;const enter=(profile={})=>{const name=profile.firstName||profile.given_name||profile.name||config.user?.name||'there';document.querySelector('#welcome-name').textContent=name;document.querySelector('#sidebar-name').textContent=name;document.querySelectorAll('.avatar').forEach(a=>a.textContent=name.slice(0,2).toUpperCase());login.classList.add('hidden');app.classList.remove('hidden');showPage(location.hash.slice(1)||'home');loadConnectedData()};document.querySelectorAll('[data-logout]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;window.havenAccessToken=null;if(keycloak){try{await keycloak.logout({redirectUri:`${location.origin}${location.pathname}`});return}catch(error){console.error('Keycloak logout failed',error)}}location.replace(`${location.origin}${location.pathname}`)}));if(new URLSearchParams(location.search).has('setup')){enter();showPage('settings');toast('Recovery mode — update or disable Keycloak below');return}if(!config.auth?.enabled){enter();return}login.classList.remove('hidden');const connect=async()=>{try{const {default:Keycloak}=await import(config.auth.adapterUrl||'https://cdn.jsdelivr.net/npm/keycloak-js/+esm');keycloak=new Keycloak({url:config.auth.url,realm:config.auth.realm,clientId:config.auth.clientId});const ok=await keycloak.init({onLoad:'login-required',pkceMethod:window.isSecureContext?'S256':false,checkLoginIframe:false});if(ok){window.havenAccessToken=keycloak.token;setInterval(()=>keycloak.updateToken(60).then(()=>window.havenAccessToken=keycloak.token).catch(()=>keycloak.login()),30000);document.querySelector('#auth-status').textContent=`Connected to ${config.auth.realm}`;enter(keycloak.tokenParsed)}}catch(err){console.error('Keycloak sign-in failed',err);login.classList.remove('hidden');const message=keycloakErrorMessage(err),errorBox=document.querySelector('#auth-error');errorBox.textContent=message;errorBox.classList.remove('hidden');clearFailedAuthCallback();toast('Keycloak sign-in failed. The detailed reason is shown on the login page.')}};document.querySelector('#login-button').onclick=()=>{document.querySelector('#auth-error').classList.add('hidden');connect()};await connect()}
start();
